<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class StoreMemberRequest extends FormRequest {public function authorize():bool{return true;}public function rules():array{return ['household_id'=>['nullable','uuid','exists:households,id'],'first_name'=>['required','string','max:100'],'last_name'=>['required','string','max:100'],'email'=>['nullable','email:rfc','max:255',Rule::unique('members','email')->ignore($this->route('member'))],'phone'=>['nullable','string','max:40'],'status'=>['required',Rule::in(['new','active','inactive'])],'gender'=>['nullable',Rule::in(['female','male','non_binary','prefer_not_to_say'])],'date_of_birth'=>['nullable','date','before_or_equal:today'],'join_date'=>['nullable','date','before_or_equal:today'],'address'=>['nullable','string','max:255'],'city'=>['nullable','string','max:100'],'state'=>['nullable','string','max:100'],'postal_code'=>['nullable','string','max:24'],'role'=>['required',Rule::in(['member','volunteer','leader'])],'photo'=>['nullable','image','mimes:jpg,jpeg,png,webp','max:2048'],'remove_photo'=>['nullable','boolean'],'ministry_group_ids'=>['array'],'ministry_group_ids.*'=>['uuid','exists:ministry_groups,id'],'emergency_contact_name'=>['nullable','string','max:150'],'emergency_contact_phone'=>['nullable','string','max:40'],'notes'=>['nullable','string','max:3000']];}}
